import { useState } from 'react';
import { Field, LookupSelect, RefName, TextInput, Tiles, ErrorText, PageProps } from '../kit';

type Id = number | string;

export default function FnSfr02702Page({ role }: PageProps) {
  const [menuId, setMenuId] = useState<Id>('');
  const [opened, setOpened] = useState<Id[]>([]);
  const [active, setActive] = useState<Id>('');
  const [memo, setMemo] = useState<Record<string, string>>({});
  const [error, setError] = useState('');

  function openMenu() {
    if (menuId === '') {
      setError('열 메뉴를 선택하세요.');
      return;
    }
    setError('');
    if (!opened.includes(menuId)) {
      setOpened([...opened, menuId]);
    }
    setActive(menuId);
  }

  function closeMenu(id: Id) {
    const next = opened.filter((x) => x !== id);
    setOpened(next);
    if (active === id) {
      setActive(next.length > 0 ? next[next.length - 1] : '');
    }
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>열린 화면</h2>
        <Tiles items={[['열린 화면 수', opened.length]]} />
      </section>
      <section className="box span-8">
        <h2>메뉴 열기</h2>
        <Field label="메뉴">
          <LookupSelect table="menu" role={role} value={menuId} onChange={setMenuId} placeholder="메뉴 선택" />
        </Field>
        <button type="button" onClick={openMenu}>열기</button>
        {error ? <ErrorText text={error} /> : null}
      </section>
      <section className="box span-12">
        <h2>업무 화면</h2>
        <div>
          {opened.map((id) => (
            <span key={String(id)}>
              <button type="button" onClick={() => setActive(id)} aria-pressed={active === id}>
                <RefName table="menu" role={role} value={id} />
              </button>
              <button type="button" onClick={() => closeMenu(id)} aria-label="닫기">×</button>
            </span>
          ))}
        </div>
        {opened.length === 0 ? <p>열린 화면이 없습니다. 메뉴를 선택해 여세요.</p> : null}
        {opened.map((id) => (
          <div key={String(id)} hidden={active !== id}>
            <h3><RefName table="menu" role={role} value={id} /></h3>
            <Field label="입력 메모" wide hint="다른 화면으로 전환해도 입력 내용이 유지됩니다.">
              <TextInput
                multiline
                value={memo[String(id)] ?? ''}
                onChange={(v) => setMemo({ ...memo, [String(id)]: v })}
              />
            </Field>
          </div>
        ))}
      </section>
    </div>
  );
}
